begin;
do $test$
declare owner_id uuid:='fad75b91-d2eb-4805-b5a3-c19e8a073bed';child_id uuid:='3666b777-1066-4eb7-a0c3-f63c2e01ae90';
 member_auth uuid;other_auth uuid;file_id uuid:=gen_random_uuid();file_path text;result jsonb;n integer;original_count integer;comment_id uuid:=gen_random_uuid();inactive_material uuid:=gen_random_uuid();
begin
 select user_id into strict member_auth from public.filhos_de_santo where id=child_id and tenant_id=owner_id;
 select u.id into strict other_auth from public.filhos_de_santo f join auth.users u on
  (f.user_id=u.id or lower(f.email)=lower(u.email) or lower(u.email) in ('f_'||f.id::text||'@axecloud.internal','filho_'||f.id::text||'@axecloud.com'))
  where f.id='1e0f70ad-b18f-497e-afbc-a160f9b20efd' and f.tenant_id=owner_id limit 1;
 select count(*) into original_count from public.biblioteca where tenant_id=owner_id;
 insert into public.piloto_biblioteca_privada(id,tenant_id,destinatario,titulo,descricao,categoria,storage_path,sha256,size_bytes)
 values(inactive_material,owner_id,child_id,'Inactive role test','','Fundamentos',owner_id::text||'/private/'||inactive_material::text||'.pdf',repeat('b',64),8);
 update public.filhos_de_santo set status='Inativo' where id=child_id;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',member_auth,'role','authenticated')::text,true);execute 'set local role authenticated';
 if public.piloto_pode_ler_pdf(inactive_material) then raise exception 'Inactive recipient can read private material';end if;
 select count(*) into n from public.piloto_biblioteca_privada where id=inactive_material;if n<>0 then raise exception 'Inactive recipient sees metadata';end if;
 execute 'reset role';
 update public.filhos_de_santo set status='Ativo' where id=child_id;
 execute 'set local role authenticated';
 if not public.piloto_pode_ler_pdf(inactive_material) then raise exception 'Activated test recipient still blocked';end if;
 select count(*) into n from public.piloto_biblioteca_privada where id=inactive_material;if n<>1 then raise exception 'Activated test recipient cannot see metadata';end if;
 execute 'reset role';
 file_path:=owner_id::text||'/private/'||file_id::text||'.pdf';
 insert into storage.objects(bucket_id,name,metadata) values('piloto_biblioteca_privada',file_path,jsonb_build_object('mimetype','application/pdf','size',8));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',member_auth,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 begin perform public.piloto_finalizar_pdf(file_id,child_id,'Validation','Description','Fundamentos',repeat('a',64),8);raise exception 'Member published PDF';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);
 begin perform public.piloto_finalizar_pdf(file_id,gen_random_uuid(),'Validation','Description','Fundamentos',repeat('a',64),8);raise exception 'Wrong recipient accepted';exception when insufficient_privilege then null;end;
 result:=public.piloto_finalizar_pdf(file_id,child_id,'Validation','Description','Fundamentos',repeat('a',64),8);
 if result->>'id'<>file_id::text or result->>'visibilidade'<>'individual' then raise exception 'Private publication unconfirmed';end if;
 result:=public.piloto_finalizar_pdf(file_id,child_id,'Validation','Description','Fundamentos',repeat('a',64),8);
 if (result->>'replayed')::boolean is not true then raise exception 'Retry created a new publication';end if;
 begin perform public.piloto_finalizar_pdf(file_id,child_id,'Different','Description','Fundamentos',repeat('a',64),8);raise exception 'Retry changed publication';exception when unique_violation then null;end;
 begin update public.piloto_biblioteca_privada set descricao='Updated description' where id=file_id;raise exception 'Published revision was edited in place';exception when insufficient_privilege then null;end;
 begin update public.piloto_biblioteca_privada set destinatario=gen_random_uuid() where id=file_id;raise exception 'Recipient change bypassed controlled flow';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',member_auth,'role','authenticated')::text,true);
 select count(*) into n from public.piloto_biblioteca_privada where id=file_id;if n<>1 then raise exception 'Intended member cannot read metadata';end if;
 perform set_config('storage.operation','object.get_authenticated',true);
 select count(*) into n from storage.objects where bucket_id='piloto_biblioteca_privada' and name=file_path;if n<>1 then raise exception 'Intended member cannot read PDF';end if;
 result:=public.piloto_comentar_pdf(file_id,comment_id,'Technical private comment');
 if result->>'id'<>comment_id::text then raise exception 'Comment not confirmed';end if;
 result:=public.piloto_comentar_pdf(file_id,comment_id,'Technical private comment');
 if (result->>'replayed')::boolean is not true then raise exception 'Comment retry duplicated';end if;
 select count(*) into n from public.piloto_biblioteca_comentarios where material_id=file_id and id=comment_id and leadership=false;
 if n<>1 then raise exception 'Comment author or visibility incorrect';end if;
 begin perform public.piloto_comentar_pdf(file_id,comment_id,'Changed comment');raise exception 'Comment retry changed content';exception when unique_violation then null;end;
 begin perform public.piloto_comentar_pdf(file_id,gen_random_uuid(),' ');raise exception 'Blank comment accepted';exception when invalid_parameter_value then null;end;
 delete from public.piloto_biblioteca_privada where id=file_id;get diagnostics n=row_count;if n<>0 then raise exception 'Member deleted material';end if;
 begin delete from storage.objects where bucket_id='piloto_biblioteca_privada' and name=file_path;get diagnostics n=row_count;if n<>0 then raise exception 'Member deleted object';end if;exception when insufficient_privilege then null;end;
 select count(*) into n from storage.objects where bucket_id='piloto_biblioteca_privada' and name=file_path;if n<>1 then raise exception 'Private object was removed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_auth,'role','authenticated')::text,true);
 select count(*) into n from public.piloto_biblioteca_privada where id=file_id;if n<>0 then raise exception 'Another member sees private metadata';end if;
 select count(*) into n from public.piloto_biblioteca_comentarios where material_id=file_id;if n<>0 then raise exception 'Another member sees private comments';end if;
 begin perform public.piloto_comentar_pdf(file_id,gen_random_uuid(),'Unauthorized');raise exception 'Another member commented';exception when insufficient_privilege then null;end;
 select count(*) into n from storage.objects where bucket_id='piloto_biblioteca_privada' and name=file_path;if n<>0 then raise exception 'Another member sees private PDF';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
 select count(*) into n from public.piloto_biblioteca_privada where id=file_id;if n<>0 then raise exception 'Another house sees material';end if;
 select count(*) into n from storage.objects where bucket_id='piloto_biblioteca_privada' and name=file_path;if n<>0 then raise exception 'Another house sees PDF';end if;
 execute 'reset role';execute 'set local role anon';
 begin perform public.piloto_pode_ler_pdf(file_id);raise exception 'Anonymous can call private reader';exception when insufficient_privilege then null;end;
 select count(*) into n from storage.objects where bucket_id='piloto_biblioteca_privada' and name=file_path;if n<>0 then raise exception 'Anonymous can read private object';end if;
 execute 'reset role';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 result:=public.piloto_comentar_pdf(file_id,gen_random_uuid(),'Technical leadership reply');
 select count(*) into n from public.piloto_biblioteca_comentarios where material_id=file_id;if n<>2 then raise exception 'Leadership cannot read discussion';end if;
 delete from public.piloto_biblioteca_privada where id=file_id;
 execute 'reset role';
 if exists(select 1 from public.piloto_biblioteca_comentarios where material_id=file_id) then raise exception 'Discussion not removed with material';end if;
 if (select count(*) from public.biblioteca where tenant_id=owner_id)<>original_count then raise exception 'Legacy acervo was changed';end if;
 if (select public from storage.buckets where id='piloto_biblioteca_privada') then raise exception 'Private bucket is public';end if;
end $test$;
rollback;
select 'passed' as pilot_private_library_validation,'fixtures and objects rolled back; existing acervo unchanged' as persistence;
